def urlopen_keep_trying(url):
    for i in range(3):
        try:
            f = urllib.request.urlopen(url)
            return f
        except urllib.error.HTTPError as error:
            if error.code in (403, 404, 416):
                raise
        except urllib.error.URLError:
            pass
        sleep(2)


